<?php require_once __DIR__.'/../includes/functions.php';if(logged_in()){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=db()->prepare('SELECT * FROM admins WHERE email=? LIMIT 1');$s->execute([trim($_POST['email']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['full_name'];header('Location: index.php');exit;}$error='Invalid email or password.';}catch(Throwable $e){$error='Database not configured. Run install.php first.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login | Plateau Digital</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="install-page"><main class="login-card"><img class="login-logo" src="../assets/images/plateau-digital-logo.jpg"><h1>Administrator Login</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><label>Email address<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn" type="submit">Sign in</button></form><a class="back-link" href="../index.php">← Back to website</a></main></body></html>
